// Generated from the original per-language whats-new page, then edited by hand.
// Prose lives here; the markup around it lives in components/WhatsNew.astro.
// `{VERSION}` in a CTA label is replaced at render time.
import type { WhatsNewData } from './types';

const data: WhatsNewData = {
  version: "4.14.9",
  meta: {
    title: "What's new in SoloMD {VERSION} — release notes v4.0 – v4.11",
    description: "SoloMD {VERSION} release notes. v4.11: malformed tables from AI/PDF exports now auto-repair and render, plus opt-in numbered-section headings (6.2 → h2) across app, CLI and MCP. v4.8: image hosting (PicGo / SM.MS / S3 / GitHub) + quality-of-life fixes (select-all, trash-safe delete, unified line breaks). v4.7: Windows editor rewritten on native textareas — CJK IME finally reliable. v4.6: knowledge graph (typed relationships, saved views, properties inspector) + tldraw whiteboards. v4.0: the agent-native author release — Inline Agent Panel, Scheduled Recipes, Trace View, MCP Federation.",
  },
  breadcrumb: {
    home: "Home",
    current: "What's new",
  },
  hero: {
    date: "Sep 2026",
    h1: "The editor where agents live.",
    lead: "v4.0 is the <strong>agent-native author</strong> release. The\n        agent goes from \"external tool you run a CLI for\" to a\n        first-class editor surface — works continuously, across multiple\n        vaults, with full visibility, replay, and rollback. Everything\n        below is in core. No plugin tax. ~15 MB still.",
  },
  cta: ["⬇ Download v{VERSION} (Mac)", "Download (Windows)", "All assets →"],
  sections: [
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.9</span>\n          <time>Oct 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.9 — the full editor on Windows again, a faster start, and every command in the menus.</h2>\n        <ul>\n          <li><strong>Windows uses the full editor again</strong> on current Windows (WebView2 154 and newer), with Microsoft Pinyin, Sogou and other input methods typing correctly in our tests. If you picked the native editor yourself, that choice is kept.</li>\n          <li><strong>Faster start:</strong> about half the work SoloMD did while starting is gone.</li>\n          <li><strong>Menus hold everything:</strong> every command in the command palette now also has a menu entry — Quick Capture, daily notes, Inbox, Sync & History, case and Chinese conversion.</li>\n          <li><strong>File tree:</strong> the × now hides the tree instead of closing your document (Close Folder moved into the folder name’s menu), and “reveal file’s folder on open” no longer brings back a tree you hid.</li>\n          <li><strong>Windows:</strong> Ctrl+J runs AI rewrite instead of opening a downloads page, and F5 no longer reloads the app.</li>\n          <li><strong>Thank you 张工</strong> — this release answers his latest test report.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.8</span>\n          <time>Oct 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.8 — menus that hold everything, a one-row toolbar, and thanks to 张工.</h2>\n        <ul>\n          <li><strong>Seven menus:</strong> File, Edit, Paragraph, Format, Navigate, View, Help — every feature has an entry, and menus show the shortcut you actually use.</li>\n          <li><strong>One-row toolbar:</strong> New, Open, Export, Insert, AI and the view modes are dropdowns.</li>\n          <li><strong>Typora / Word shortcut preset</strong> plus new commands for everyone: heading level up/down, back to paragraph, select word or line, delete word, reopen closed tab, F8 focus, F9 typewriter.</li>\n          <li><strong>Windows live editor:</strong> Ctrl+Home/End, Ctrl+Up/Down, triple-click and Shift+click work across paragraphs; selecting inside a code block no longer freezes; spelling suggestions are back in the right-click menu.</li>\n          <li><strong>Also:</strong> draggable split-view divider, formulas no longer clipped, wide tables wrap in PDF, Vim Enter fixed, a setting to turn off code-block language suggestions.</li>\n          <li><strong>Thank you 张工</strong> — our tester, whose careful reports led to most of this release.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.7</span>\n          <time>Oct 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.7 — your iPhone and iPad files, where you want them.</h2>\n        <ul>\n          <li><strong>Pick any folder as your workspace</strong> on iPhone and iPad — iCloud Drive, On My iPhone or another app’s folder in the Files app. SoloMD remembers it across launches.</li>\n          <li><strong>SoloMD’s folder in the Files app:</strong> On My iPhone › SoloMD now shows up, and notes opened from the Files app are edited in place — saving updates the original instead of making a copy.</li>\n          <li><strong>Rename, move and delete on touch screens:</strong> long-press a file in the file tree, or tap ⋯.</li>\n          <li><strong>After an update</strong> folders you opened before open again, instead of reporting that they are no longer there.</li>\n          <li><strong>App Store builds</strong> (iPhone, iPad, Mac) send no usage data and ask for a rating only with Apple’s own rating sheet.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.6</span>\n          <time>Oct 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.6 — links that stay links, and selections across paragraphs.</h2>\n        <ul>\n          <li><strong>Windows live edit:</strong> clicking a link no longer replaces SoloMD with the web page (which also left Esc, Alt+F4 and the close button dead) — a click puts the caret in the link, Ctrl+click opens it in your browser.</li>\n          <li><strong>Select across paragraphs</strong> in Windows live edit by dragging, in either direction, then bold, delete or type over it. Bold, italic, strikethrough and code over several paragraphs format each paragraph on its own.</li>\n          <li><strong>Ordered lists renumber themselves</strong> when you add or delete an item, in every editor.</li>\n          <li><strong>Menus:</strong> Settings moved to the File menu, Edit has Find and Replace, the zoom commands sit in View › Zoom, Help lists the Markdown cheatsheet, keyboard shortcuts and the command line separately, and the Insert menu gains headings 4–6.</li>\n          <li><strong>Also:</strong> shortcuts typed while a Chinese input method is active are recognised more robustly on Windows (Ctrl+, for Settings). And after a few days of use SoloMD asks once — only once — whether you’d like to star it on GitHub.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.5</span>\n          <time>Oct 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.5 — exports keep everything, and a Mac PDF without a printer.</h2>\n        <ul>\n          <li><strong>Exports:</strong> on macOS, Export PDF (text) now saves straight to a file — no print dialog, no printer needed. Word keeps every image (web images, images inside a sentence, a table or a list, HTML &lt;img&gt;), PlantUML diagrams appear in Word and both PDFs, the image PDF keeps web images, and the text PDF no longer drops the ∫ in formulas or prints faded code.</li>\n          <li><strong>Windows live edit:</strong> multi-line paragraphs no longer jump when clicked, and outline jumps highlight the right section. (#366, #343)</li>\n          <li><strong>Keyboard:</strong> F2 renames and Del deletes in the file tree; the unsaved-changes dialog has access keys (Save / Don’t Save); settings search steps through matches and hides empty categories; Ctrl+1 works on an empty first line. (#355, #357, #352, #360)</li>\n          <li><strong>File tree:</strong> dragging shows what the drop will do, and clicking an exported .html opens it instead of importing a new note each time. (#361, #356)</li>\n          <li><strong>Also:</strong> “Copy image” in the editor’s right-click menu on Windows, an option to stop syncing the split view (the preview refreshes on save), and choosing A4 now turns on page numbers in the PDF table of contents. (#362, #347)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.4</span>\n          <time>Sep 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.4 — sort the file tree your way, and a Russian interface.</h2>\n        <ul>\n          <li><strong>Sort the file tree</strong> by name, creation date or modification date, or drag files into your own order. New files go at the end. (#342)</li>\n          <li><strong>Settings search.</strong> Filter every settings page by name or description; English keywords work in any interface language. (#352)</li>\n          <li><strong>Steadier editing:</strong> optionally keep Markdown markers visible so lines never jump, and tint the current line. Outline jumps in preview now land on the heading, and the outline follows what you're reading. (#353, #350)</li>\n          <li><strong>Windows:</strong> a right-click menu with Cut, Copy, Paste and Select All; a portable mode that keeps settings in a <code>data</code> folder next to SoloMD.exe; and a maximize button plus a pen icon in reading mode. (#210, #295, #221)</li>\n          <li><strong>Russian</strong> joins the interface languages, and the status bar is now translated too. (#157)</li>\n          <li><strong>Exports:</strong> the PDF table of contents gets a title and page numbers, and all exports use neutral colours. (#347, #332)</li>\n          <li><strong>Also:</strong> a shortcut to flip between live edit and edit only (⌘/Ctrl+Alt+/), Quick Look previews rendered Markdown on macOS, and Android can insert images from the photo picker. (#180, #351, #349)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.3</span>\n          <time>Sep 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.3 — pasted images that show up, and a Windows editor you can choose.</h2>\n        <ul>\n          <li><strong>Pasted images show up even when the path has a space.</strong> A folder like <code>D:/Program Files/…</code> made the image link invalid Markdown, so the note showed the link text instead of the picture. Pasted, dropped and uploaded images now encode the path, and older notes with such links render in preview and export. (#345)</li>\n          <li><strong>Windows: pick the CodeMirror editor without Vim mode.</strong> Settings → Writing → Editor engine. CodeMirror gives Markdown syntax colouring and a steadier live edit; Native stays the default because it is safest with Chinese input methods. (#328, #344)</li>\n          <li><strong>The file tree follows the file you're on.</strong> Switching tabs expands the folders above the file and selects it; it can be turned off in Settings. The new-file box inside a folder now lines up with its siblings. (#333, #321)</li>\n          <li><strong>Exports:</strong> standalone HTML prints on white paper; the text PDF on Windows no longer carries the print date and file name, and can start with a table-of-contents page (Settings → PDF). (#332, #347)</li>\n          <li><strong>Quieter screen:</strong> hide the toolbar buttons with ⌘/Ctrl+Alt+Shift+T, and the AI rewrite button stays hidden until AI is enabled. Community themes now apply fully whichever built-in theme is selected. (#346)</li>\n          <li>The About dialog now thanks the project's sponsors.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.2</span>\n          <time>Sep 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.2 — exports that hold together, and a friendlier file tree.</h2>\n        <ul>\n          <li><strong>“Open in default app” works again.</strong> A misplaced permission rule meant every “open with the system app” action was refused on every platform — the toolbar button, linked PDFs/Office files, the dictionaries folder. Any file can be opened now; executables and scripts are still refused. (#331)</li>\n          <li><strong>Printed PDFs print every page.</strong> The text PDF stopped after the first page; long tables now repeat their header on each page. The image PDF no longer cuts through a line of text or a table row at a page break. (#337)</li>\n          <li><strong>Standalone HTML is truly standalone.</strong> Mermaid diagrams are embedded as SVG instead of showing their source, math styles and fonts are embedded instead of loaded from a CDN (so the file opens instantly, offline too), and local images are embedded. Word export now includes Mermaid diagrams as images. (#332, #256, #313)</li>\n          <li><strong>Lists continue on Enter</strong> in the Windows edit and split views, including numbered lists, task lists and quotes; Enter on an empty item ends the list. (#341)</li>\n          <li><strong>File tree:</strong> delete asks first (and still goes to the Trash), folder icons and indent guides, a highlighted selection that decides where new files go, an optional double-click to open folders, ⌘/Ctrl+Alt+Shift+N for a new note in the selected folder, and “Reveal in File Tree” that actually scrolls to the file. (#338, #340, #333)</li>\n          <li><strong>Smaller fixes:</strong> Esc closes the image viewer (#339); typing <code>```</code> suggests fence languages (#297); on Windows, the folder picker can choose the Desktop (#334).</li>\n          <li>Several of these fixes come from <a href=\"https://github.com/chenghaitao/solomd\">@chenghaitao’s fork</a> — thank you.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.1</span>\n          <time>Sep 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.1 — fixes for the things that fought back.</h2>\n        <ul>\n          <li><strong>Find on Windows no longer eats what you searched for.</strong> Enter / Shift+Enter step through matches and focus stays in the find box, so a second Enter can’t replace the match with a line break. Typing jumps to the first match after the cursor, the current match is highlighted, the view stays on it while the page finishes rendering, and the box steps aside when it would cover it. Esc hands the editor the match. (#330)</li>\n          <li><strong>The table editor types forwards.</strong> Typing in a cell came out reversed (“abc” → “cba”) on every platform. (#319)</li>\n          <li><strong>Split panes can be closed.</strong> Dragging a tab onto the editor splits it, and the extra pane had no visible way out — it even survived a restart. Each pane now has a close button. (#263, #306)</li>\n          <li><strong>Every open tab is one click away.</strong> When tabs overflow the strip, a ⌄ button lists them all. (#218)</li>\n          <li><strong>File tree:</strong> new files and folders are named where they will appear, not at the top (#321); long names use the sidebar’s full width (#259); image attachment folders (<code>_assets</code>, <code>*.assets</code>) are hidden unless “Show hidden files” is on (#325).</li>\n          <li><strong>Tables:</strong> short cells no longer get squeezed into a vertical column beside a long one — in the app and in PDF / HTML / image export. (#271)</li>\n          <li><strong>Also:</strong> clicking empty space in Windows live edit puts the caret in the text (#326); menus use the window’s height instead of scrolling at 360px (#320); on phones the expanded toolbar fits the screen, so Settings is reachable in portrait (#329).</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.0</span>\n          <time>Sep 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.0 — keys for the things you type all day, and a way to find them.</h2>\n        <ul>\n          <li><strong>Formatting has shortcuts.</strong> Bold, italic, strikethrough, inline code, link, headings 1–6, quote, the three kinds of list and code block — sixteen commands, each a toggle: press it on a selection to apply, again to remove. With nothing selected it acts on the word under the cursor. They work in all three editors SoloMD is, including the Windows one, and every one can be rebound. (#296, #274)</li>\n          <li><strong>Ctrl+B for bold is one click away, not forced on anyone.</strong> Ctrl+B has toggled the file tree since 1.0, so bold ships on Ctrl+Shift+B. If your hands expect Typora or Word, the Writer preset at the top of Settings → Shortcuts swaps the two — and swaps them back.</li>\n          <li><strong>Sixty shortcuts you can actually find.</strong> F1 → Shortcuts is now generated from your live bindings instead of a hand-kept list that had drifted, and it is searchable by name, in your language or English, or by the key itself. The same search is in Settings. The Insert menu leads with the formatting commands and shows each one’s key. And the first time you type a piece of formatting by hand, a small tip names the key for it — once per kind, and there is a switch to turn it off.</li>\n          <li><strong>Windows: Find goes to the match.</strong> In a long document the counter advanced while the view stayed where it was, because selecting text in a text box does not scroll it. In live edit the match could sit thousands of pixels off-screen inside a long code block. Both fixed, and verified on Windows. (#255)</li>\n          <li><strong>Windows: clicking into a paragraph no longer moves the page.</strong> The block you left re-rendered at a different height and the one you entered scrolled itself into view. The block under the pointer now stays under the pointer, and dragging to select rendered text no longer drops you into edit mode. (#300, #240)</li>\n          <li><strong>Smaller fixes.</strong> The Hunspell dictionary picker appears under the Hunspell checkbox, where it belonged, instead of under the browser spell-check toggle (#246). Blank lines in a numbered code block keep their row instead of stacking their numbers (#190). A standalone [TOC] line expands into a table of contents (#289, thanks @Zxis233).</li>\n          <li><strong>iOS waits for a later build.</strong> Apple’s iOS 27 requires a change in the framework SoloMD is built on that has not been released yet, so this version ships for macOS, Windows, Linux and Android. The App Store version stays on 4.13.0, which is unaffected.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.13.3</span>\n          <time>Sep 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.13.3 — a file that changed behind your back, and a button that did nothing.</h2>\n        <ul>\n          <li><strong>A file changed by another editor is noticed now.</strong> Open tabs are restored with the text they had when SoloMD closed, and nothing ever compared that against the file — so a note edited elsewhere in the meantime kept showing the old version, and opening it again did nothing, because a file that is already open was only brought to the front. The file system watcher could not help: it reports changes while the app runs, not while it is closed, and it deliberately ignores events that look like our own writes. Every open file is now re-read at launch and whenever the window comes back. Unsaved edits are never overwritten — those still get the “this file changed” prompt, and a prompt you dismissed is not raised again for the same content. (#317)</li>\n          <li><strong>The right sidebar button always does something.</strong> It flipped a hidden/shown flag, but the strip is only drawn when a pane inside it can actually render — and most of them need a workspace folder. With no folder open, or after closing the AI panel, the button changed a flag and nothing else: the first press appeared dead, and only switching the Outline on ever “repaired” it. It now goes by what is on screen, and turning the strip on makes sure something in it can draw.</li>\n          <li><strong>Shortcuts that other software takes are named, with somewhere else to put them.</strong> On a machine with an AMD card, seven of the default Ctrl+Shift chords never reach SoloMD: AMD Software registers them as global hotkeys, so the driver answers instead. Microsoft Pinyin takes one more. The app cannot see a key that never arrives, so Settings → Shortcuts now lists the affected commands, says who takes each one, and offers to move them to free keys in one click. Defaults are unchanged for everyone else, and “Reset all” undoes it.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.13.2</span>\n          <time>Sep 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.13.2 — the two writing settings Windows quietly ignored.</h2>\n        <ul>\n          <li><strong>Focus mode and the solid cursor now work with Vim mode off.</strong> Windows does not run the same editor as everyone else: since 4.7 it uses plain text boxes, because WebView2 drops the first character of Chinese input and doubles its punctuation. Both of these settings were features of the other editor, so on Windows there was no code behind either switch — and turning Vim mode <em>on</em> appeared to fix them, because that is what brings the other editor back. Both are implemented for the Windows editor now: in live edit the block you are writing in stays lit while the rest dims, and in edit and split view everything outside the current paragraph dims. The solid cursor is drawn by hand there, since no stylesheet can stop a native text cursor blinking; it hands the native one back while an input method is composing, so the cursor never disappears mid-word. (#316)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.13.1</span>\n          <time>Sep 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.13.1 — a note that could run code, and a toolbar that ate the filename.</h2>\n        <ul>\n          <li><strong>A note can no longer run JavaScript.</strong> Inline HTML in a markdown file was rendered straight into the app, with no sanitiser anywhere and no content-security policy — so <code>&lt;img src=x onerror=…&gt;</code> in someone else's note executed inside the editor, where the app's own file-reading and file-writing commands live. The code comment next to it justified this with “this app only ever renders the user’s own files”; that was wrong, and a reporter proved it. Notes travel: shared vaults, downloaded files, Git-synced folders, AI output. Rendered markdown is now sanitised everywhere it is shown — preview, live edit, slideshow, and every export. Inline HTML still works, because real documents use it; scripts, event handlers and <code>javascript:</code> links do not. Uploading an SVG that carries a script is refused as well, since an image host serves it as a document on its own domain. <strong>If you opened untrusted markdown in an earlier version, this is the update to take.</strong> (#304)</li>\n          <li><strong>The document name stopped disappearing on narrow windows.</strong> It was the only part of the toolbar allowed to shrink, so when the strip didn't fit it absorbed the entire squeeze alone — measured 8 pixels wide, which renders as a single clipped letter and reads as the name being covered up. (#309, #282)</li>\n          <li><strong>The overflow toolbar is a third of the height.</strong> Opening “⋯” produced a 195px block — a quarter of a 768px screen — with a 378px gap in the middle of the second row, because the spacer that centres the view buttons in one row had nothing to push apart once it wrapped. It is now two rows of ordinary icons at 72px, and on a desktop it stays open after a click instead of folding away before every action. Both changes are what the reporter asked for after trying the first version. (#282)</li>\n          <li><strong>Picking a dark theme when nothing changes now explains itself.</strong> Fourteen of the fifteen marketplace themes define their colours for light and dark at once, so an installed theme wins both slots and the built-in dropdown stops changing anything. Nothing said so, and the custom-CSS setting sits three categories away. The dropdown now names the theme that is overriding it, with one click to turn it off. (#282)</li>\n          <li><strong>Mermaid diagrams render when exporting a text PDF.</strong> The image export and the preview each turn a diagram into a picture after rendering; the text path never did, so it printed the diagram's source. Printing also stopped fetching its maths stylesheet from a CDN — an offline-first editor was making a network request every time you printed, and losing all equation styling without a connection. (#301)</li>\n          <li><strong>The app starts faster.</strong> Every dependency was being compiled before the first frame, whether the document needed it or not — the diagram renderer, both Chinese dictionaries, the PDF and Word exporters, the slideshow. They now load when something actually asks for them: half the startup code is gone and first paint is about 30% quicker. The difference is largest on the slower machines the reports came from.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.13.0</span>\n          <time>Sep 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.13.0 — the file tree can finally be organised.</h2>\n        <ul>\n          <li><strong>Files and folders can be dragged where they belong.</strong> Moving a note into a subfolder used to mean leaving for Finder / Explorer — the tree could rename but not move. Now you drag a node onto a folder; keyboard and touch users pick “Move to…” from the context menu, type a few letters to filter the folder list and press Enter. Moves are undoable, open tabs follow (including every tab <em>inside</em> a moved folder), and <strong>relative links are re-anchored</strong> — a note that drops one level down has <code>_assets/shot.png</code> rewritten to <code>../_assets/shot.png</code>, so its images don’t break. Three people asked for this. (#290, #267, #273)</li>\n          <li><strong>Hidden files can be shown.</strong> <code>.gitignore</code>, <code>.obsidian/</code>, or a whole vault of dot-prefixed notes were unreachable from inside the app — only the file manager could see them. New setting, off by default: most people don’t need <code>.git</code> in their face.</li>\n          <li><strong>The file tree can be filtered by file type.</strong> The list offers the extensions your vault <strong>actually contains</strong>, with counts — not a canned list of twenty formats. Pick <code>.txt</code> and folders whose subtree holds no txt collapse away too; a filter that still shows every folder until you open it is a suggestion, not a filter. While it’s on, a banner at the top of the tree names the active types and clears them in one click, so it can never read as “my files are gone”. (#282)</li>\n          <li><strong>The editor and preview panes can be told apart in split view.</strong> Side by side they were the same surface, so the split read as one wide column. Turn it on and the preview gets a shade of its own — derived from the current theme, so it works across all eight without any per-theme tuning. (#279)</li>\n          <li><strong>A window too narrow for the toolbar no longer clips it silently.</strong> On a 1366×768 screen the strip needs 1532px, so 166px of it — several buttons and the document title — sat outside the window. It has always scrolled sideways; nothing ever said so. Now a “⋯” appears when the row overflows and opens the whole toolbar as two or three labelled rows, where every control is visible and named. (#282)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.12.1</span>\n          <time>Sep 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.12.1 — text that ran off the page, and menus you couldn&#39;t reach.</h2>\n        <ul>\n          <li><strong>Pasted text no longer runs off the page.</strong> When a document&#39;s spaces come from Word, a web page or a chat transcript, they are often non-breaking spaces rather than ordinary ones — the file behind one report had 119 of them against 23 real spaces. A paragraph glued together that way is a single unbreakable word as far as any layout engine is concerned, so it simply left the column: sideways scrolling in the preview, and text clipped off the edge of an exported PDF. Fixed in the preview, PDF export, printing and HTML export alike. Live edit was never affected, which is exactly what made it look like a rendering bug. (#293)</li>\n          <li><strong>The Outline pane can fill the sidebar again.</strong> Drag the divider while Outline shares the sidebar with another panel, then close that panel, and Outline stayed pinned at the height it had — a four-row box in a sidebar three times as tall, with no divider left to drag, because dividers only exist between panels. A panel that has the sidebar to itself now fills it, the bottom panel absorbs whatever the ones above leave over, and the divider shows itself on hover instead of being an invisible four-pixel line. (#294)</li>\n          <li><strong>The AppImage installs in AppImage managers.</strong> It always ran when launched directly, but tools that unpack it — AppManager, Gear Lever — refused it outright. The bundler had baked in an absolute symlink pointing at the build machine&#39;s own disk, a path that exists on nobody else&#39;s computer. (#291)</li>\n          <li><strong>GitLab and self-hosted git remotes have somewhere to put the URL.</strong> Choosing &quot;Custom HTTPS git URL&quot; led to a token box and then an empty panel: no field, no button, while the hint just above it asked you to paste a clone link. Those remotes have no repository list to browse, so pasting the URL <em>is</em> the flow — and it was the one thing missing. Signing out was missing for them too.</li>\n          <li><strong>The slash menu can be scrolled with the keyboard.</strong> Pressing Down walked the highlight to the ninth item and appeared to stop, and a list scrolled with the mouse snapped straight back to the top — so everything below the divider, whiteboards included, was unreachable. The popup was being destroyed and rebuilt on every keystroke, which reset the scroll position and skipped the code that keeps the highlighted row in view.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.12.0</span>\n          <time>Sep 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.12.0 — fold it, print it, undo it.</h2>\n        <ul>\n          <li><strong>Fold a heading and everything under it.</strong> Click the arrow in the gutter, or use the Fold commands to collapse a section, every section, or everything below a level. The model is a plain text scan rather than a CodeMirror feature, so it works the same in the plain-textarea editor Windows uses.</li>\n          <li><strong>Printing no longer follows your app theme.</strong> A dark theme used to print dark — ink on paper, or a PDF nobody could read. Print and PDF now use their own light palette, with an explicit dark option if that is what you actually wanted.</li>\n          <li><strong>Deleting a file gives you eight seconds to undo.</strong> The delete is held rather than the file moved somewhere clever: it stays exactly where it is until the timer runs out. Anything that needs the filesystem settled first — creating, renaming, switching workspace, closing the window — flushes the pending delete before it acts.</li>\n          <li><strong>Quick capture, from anywhere.</strong> A system-wide chord (⌘⌥M by default) opens a small box over whatever you are doing. Type a line, press Enter, and it lands in your Inbox without SoloMD ever coming forward.</li>\n          <li><strong>A Tasks panel.</strong> Every <code>- [ ]</code> in the workspace, in one list. Priorities and due dates are read from either the Obsidian Tasks emoji (<code>⏫</code>, <code>📅 2026-09-10</code>) or a plain-ASCII form (<code>!!!</code>, <code>due:2026-09-10</code>), so an existing vault keeps working and nobody has to reach for an emoji picker mid-sentence. Click a task to jump to its line; tick it to write the file.</li>\n          <li><strong>Import Word, PDF, HTML and spreadsheets.</strong> The converters were already in the app with no way to reach them. There is now a menu entry — and importing a name that already exists picks the next free one instead of overwriting, compared case-insensitively, because Windows and macOS disagree about what counts as a collision.</li>\n          <li><strong>Edit a table as a grid.</strong> Add and remove rows and columns without counting pipes. CJK text is padded by display width, so the Markdown source stays aligned in a monospace font instead of drifting one column per Chinese character.</li>\n          <li><strong>DOCX templates.</strong> Cover page, table of contents, running header, page numbers — three presets, or set per document with a <code>docx:</code> block in the front matter.</li>\n          <li><strong>Numbered equations and cross-references.</strong> <code>\\label</code> on a display equation gets a number and an anchor; <code>\\eqref</code> becomes a link that jumps to it.</li>\n          <li><strong>A deleted workspace folder no longer looks like an empty vault.</strong> If the folder went away underneath us, the tree showed nothing under its own name — indistinguishable from having lost every file in it. It now says the folder is missing, and clears the warning by itself when the folder comes back.</li>\n          <li><strong>The file-tree context menu printed key names.</strong> Four strings were never defined in any language, so the menu showed <code>explorer.copyGitUrl</code> instead of a label — in all fourteen. Defined everywhere now.</li>\n          <li><strong>For agents: <code>list_tasks</code> in the MCP server.</strong> Every checkbox in the workspace with its file, line and done state, matching what the Tasks panel shows — so an agent and the panel cannot disagree about which line to tick.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.22</span>\n          <time>Sep 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.22 — things that quietly did nothing.</h2>\n        <ul>\n          <li><strong>File → New Window opened no window.</strong> The menu item fired an event nothing listened for, so it had been inert since the day the native menu shipped — while the same action from the command palette worked, which is why it read as \"nothing happens\" rather than an error. Both now take the same path, and a window that fails to open says so instead of failing silently.</li>\n          <li><strong>A text file opened blank after live-edit.</strong> On Windows, switching from a markdown file in live-edit mode to a .txt file showed an empty editor with the line numbers still counting the missing text. The content was never lost — the gutter and the editor were being filled at different moments, and only the gutter won. Switching away and back used to be the workaround; now it just opens.</li>\n          <li><strong>[[folder/note]] links made a second, empty note.</strong> A wikilink with a folder in it never resolved, so clicking it created a duplicate beside the note you were linking to. Folder paths, frontmatter aliases, and files created since the last scan all resolve now. Thanks to <a href=\"https://github.com/jukejeew\">@jukejeew</a>.</li>\n          <li><strong>Linux: File → Exit, with Ctrl+Q.</strong> Tiling window managers hide the title bar, leaving no ✕ and no obvious way out. Also from <a href=\"https://github.com/jukejeew\">@jukejeew</a>.</li>\n          <li><strong>No more full-screen flicker while dragging the splitter</strong>, and a custom theme that would reintroduce it now says so when it loads. Thanks to <a href=\"https://github.com/raopan2021\">@raopan2021</a>.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.21</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.21 — the shortcuts page you couldn't see.</h2>\n        <ul>\n          <li><strong>Settings → Shortcuts opened onto an empty page.</strong> 4.11.20 shipped the rebinding feature with its settings page invisible: the panel shows one category at a time through a CSS whitelist, and the new Shortcuts category was never added to it, so the hide rule caught the markup and nothing brought it back. Everything was there and working — you just couldn't see it. The whitelist now covers all seven categories.</li>\n          <li><strong>Downloads you can verify yourself.</strong> Every release now carries a <code>SHA256SUMS.txt</code> covering all its files, so you can check what you downloaded is what we built.</li>\n          <li><strong>About Chrome's \"scanning\" notice on Windows.</strong> The Windows builds aren't code-signed yet, so Chrome's Enhanced Protection scans each new version and then reports no virus found — that is a pass, not a warning. Separately, 4.11.20's x64 installer tripped a machine-learning false positive in Microsoft Defender, which is why that download was briefly held back at 4.11.19. Every release is now scanned with Defender before it goes out, and 4.11.21's x64 installer scans clean — so Windows x64 is current again.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.20</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.20 — the shortcuts are yours now.</h2>\n        <ul>\n          <li><strong>Every app shortcut can be changed.</strong> Settings → Shortcuts lists 37 actions grouped by File / Edit / View / Navigate / Tools. Click Change, press the chord you want, and it applies immediately — no restart. You can unbind an action entirely (if you want ⌘E or ⌘D back for something else, take it), reset one to its default, or restore all of them. Trying to take a chord another action already holds is refused with the name of the action holding it, rather than quietly creating two owners for one key.</li>\n          <li><strong>Changing a shortcut changes it everywhere.</strong> The chord you set is what the toolbar tooltips say, what the Markdown cheatsheet's shortcut table shows, what the command palette lists, and — the part that actually matters on macOS — what the native menu bar holds. Previously the menu owned ⌘S at the operating-system level, so rebinding Save would have left ⌘S <em>also</em> saving; the menu is now rebuilt with your chords, and an unbound action loses its menu accelerator entirely.</li>\n          <li><strong>Including the editor's own ⌘J.</strong> AI Rewrite lives in the editor's keymap rather than the app's, and it is rebindable too — the change reaches an already-open editor, not just the next one you open. The keys that only mean something inside a popup (arrows, Tab, Enter, Esc) stay fixed, as do the ones the operating system owns: undo, cut, copy, paste.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.19</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.19 — the phone stops being a shrunken desktop.</h2>\n        <ul>\n          <li><strong>A layout built for a phone.</strong> Measured on a 390px screen before this release: the file tree took 250px and the right sidebar another 260 — of 390 — so the editor was a sliver or gone entirely; split view left each pane about 195px; the status bar wrapped onto a second line; and the toolbar was a ribbon of 29 icons you swiped through. The side panes are now drawers that float over the editor and close with a tap outside, so the editor always has the full width. Split stacks the panes vertically instead of side by side. The toolbar keeps six controls — file tree, save, the three view modes, search — and a \"more\" that expands the bar into a sheet where every remaining control has an icon <em>and</em> a label; nothing became unreachable. The status bar keeps the counters that move while you type and drops the desktop reference values. Settings stops being a 160px nav rail beside a 145px column. <strong>Tablets are deliberately untouched</strong> — the layout follows the viewport, not the operating system, so an iPad keeps the desktop arrangement and a desktop window dragged narrow gets the phone one.</li>\n          <li><strong>Bold that ends in a full-width punctuation mark now renders.</strong> <code>**限制：**硬链接</code> came out as literal asterisks. The closing <code>**</code> sits after a full-width colon and before a Han character, and CommonMark says a run in that position can't close — a shape that is everywhere in Chinese writing. SoloMD now follows the CommonMark CJK amendment, which reads those rules as <em>non-CJK</em> punctuation. Both engines were fixed: the preview/export renderer and the separate parser behind live edit, so the two panes can't disagree about the same document. ASCII is unchanged.</li>\n          <li><strong>A multi-line <code>$$</code> formula stays in one piece on Windows.</strong> A block using <code>\\begin&#123;aligned&#125;</code> was split into three, with the indented middle line rendered as a grey code block. The Windows editor's block splitter knew about ``` fences but not about <code>$$</code>, so it walked into the formula line by line — and any line indented four spaces, which is routine inside <code>aligned</code>, became an indented code block of its own.</li>\n          <li><strong>Exporting starts in the document's own folder.</strong> The save dialog was given only a filename, so the system reused wherever you last saved — export a note from your notes folder and the dialog could still open in last week's Downloads.</li>\n          <li><strong>The first-run AI setup offers every provider, and a base URL.</strong> It listed four brands while Settings had sixteen, and had no address field at all — so anyone using a relay endpoint or a self-hosted server had to skip the wizard entirely. It now shows the full list with an editable base URL, and providers that need no account no longer demand a key. Separately, verification no longer fails on endpoints that don't serve a model list: a gateway that returns 404 for <code>/v1/models</code> while chat works perfectly is now verified with a one-token chat instead. A wrong key still fails, as it should.</li>\n          <li><strong>Reading mode uses the font you chose.</strong> It declared its own serif stack and swallowed the setting whole — the code comment even claimed you could override it. On a phone its exit button also sat on top of the first heading; it moves to the bottom right, where a thumb can reach it.</li>\n          <li><strong>The macOS install script works again.</strong> <code>curl -fsSL https://solomd.app/install.sh | bash</code> failed for every macOS user with \"Failed to mount DMG\" — the script silenced the very output it then tried to read the mount point out of. Thanks to the reporter, whose diagnosis was exact.</li>\n          <li><strong>Code blocks have a copy button while you edit.</strong> In live-edit mode a fenced block <em>looks</em> rendered — the ``` lines are hidden — but selecting it by hand still gave you the source: the fences, and, for a block nested in a list, the two spaces of list indentation in front of every line. Paste that into a terminal and you get to strip it by hand. Every code block now carries the same one-click copy button the preview pane has, and it copies what a renderer would: no fences, the block's own indentation removed, the code's own indentation kept. Present in all three places code is shown — the live editor, the preview pane, and the Windows block editor.</li>\n          <li><strong>Ollama on another machine is detected.</strong> If you ran Ollama on a NAS or a desktop across the room and put its address in Base URL, Settings → AI insisted \"not detected\" — the probe ignored that field and always asked localhost, even though chat itself was talking to your server perfectly well. It now follows the address you set, re-checks as you type it, tells you exactly what it probed, and when a remote box doesn't answer it says what to check (a remote server needs <code>OLLAMA_HOST=0.0.0.0</code> and an open port) instead of offering to install Ollama on your laptop.</li>\n          <li><strong>New provider: any OpenAI-compatible server you host yourself</strong> — llama.cpp's <code>llama-server</code>, LM Studio, vLLM, LocalAI, an internal gateway. Previously the only way in was to borrow another provider's slot, and it didn't work: a key was mandatory (so people invented one) and a bare <code>host:port</code> — exactly what those servers print at startup — 404'd because the <code>/v1</code> prefix was assumed to be typed already. Now the key field is optional, the address is completed for you, the model list is read from the server, and if it can't connect you see the server's own answer (<code>HTTP 404</code>, connection refused) plus what to check. Usable from recipes too: <code>provider: openai-compat</code> (or <code>llama-cpp</code> / <code>lmstudio</code> / <code>vllm</code>).</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.17</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.17 — the Option-key shortcuts, and one stall Linux can no longer take.</h2>\n        <ul>\n          <li><strong>Every ⌘⌥ shortcut works on macOS.</strong> macOS folds Option+letter into a different glyph before the keystroke ever reaches us — Option+N arrives as \"Dead\", Option+P as \"π\", Option+C as \"ç\" — and we were matching on the letter, so <kbd>⌘⌥N</kbd> (new text file), <kbd>⌘⌥P</kbd> (slideshow), <kbd>⌘⌥⇧P</kbd> (print to PDF), <kbd>⌘⌥B</kbd> and <kbd>⌘⌥L</kbd> had simply never fired on a Mac. They now match on physical key position. While we were there, <strong><kbd>⌘⌥C</kbd> copies the selection as Markdown</strong> — the one copy format people actually paste elsewhere, and the only one without a shortcut.</li>\n          <li><strong>Linux: SoloMD no longer waits on an accessibility service that isn't answering.</strong> When the desktop's AT-SPI bus accepts a call and never replies, GTK and WebKit each block the interface for their full D-Bus timeout — 25 s and 30 s — before the window can paint or take a click. SoloMD now asks that bus itself, with a two-second budget, before GTK starts: if it answers, nothing changes and screen readers work exactly as before; if it doesn't, we start without accessibility instead of waiting on it. Measured on a rig with a deliberately wedged bus, launch-to-usable went from 51 s to 3 s.<br /><strong>This is not a fix for the freezes reported on Arch and Ubuntu (<a href=\"https://github.com/zhitongblog/solomd/issues/253\">#253</a>, <a href=\"https://github.com/zhitongblog/solomd/issues/200\">#200</a>).</strong> Those never recover on their own; this stall always did, so it is something else, and that investigation is still open. If you are hitting one of those, the issues are the place to follow along.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.16</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.16 — the cursor stays where you put it.</h2>\n        <ul>\n          <li><strong>The caret no longer jumps away while you type on Windows.</strong> If anything touched the open file from outside — a cloud client syncing it, a sync pull, a save round-trip — SoloMD reloaded the buffer and the cursor was thrown to the other end of the document. Sometimes letters stopped going in at all, because the same event interrupted an in-flight IME composition or knocked focus out of the editor, at which point single keystrokes were being read as shortcuts. A fix for this existed since 4.11.1 but only covered the CodeMirror editor; Windows runs a native text box and never received it.</li>\n          <li><strong>Gitee sync works.</strong> It could not authenticate at all: we sent the Basic-auth username GitHub requires, and Gitee rejects it outright — so every attempt failed no matter how valid the token was. Verified end-to-end against a real Gitee repository now. (#249)</li>\n          <li><strong>The agent can actually write when you let it.</strong> \"Allow the agent to write in the vault\" had no effect — the write tools were never sent to the model, so it answered that it had none. And recipe runs finished on their branch but never appeared in \"Pending review\", so they could not be accepted or rejected. Both traced by <a href=\"https://github.com/jclg83\">@jclg83</a>. (#247, #248)</li>\n          <li><strong>Spell-check in your language.</strong> The checker was pinned to English, which flagged every word for everyone else. Pick a dictionary in Settings → Writing, and drop any Hunspell <code>.aff</code> + <code>.dic</code> pair into the folder the button opens. (#246)</li>\n          <li><strong>Case conversion.</strong> <kbd>Shift+F3</kbd> cycles the selection — or the word under the cursor — through lower / UPPER / Title, with explicit commands in the palette. Requested on Gitee.</li>\n          <li><strong>Curly quotes are off for good.</strong> Making them opt-in in 4.11.11 only changed the default, so everyone who already had them kept seeing a wide gap after apostrophes on CJK fonts. Now cleared once, and it stays off unless you turn it back on. (#251)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.15</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.15 — three things Gitee had been telling us for weeks.</h2>\n        <ul>\n          <li><strong>Slash commands did nothing on Windows unless you were in Live Edit.</strong> Windows runs a plain text box rather than CodeMirror, because WebView2 drops characters during Chinese input — and the replacement autocomplete had only ever been wired to the Live Edit block editor. In 仅编辑 and 分栏 the popup never appeared, could not be navigated, and could not insert. It was not only the slash menu: <code>[[</code> wikilinks, <code>#</code> tags and <code>@</code> citations share the same trigger and were equally dead. All four now work in every mode, with the popup following your cursor line. (Gitee IK6JCC)</li>\n          <li><strong>The two PDF exports now say what they actually produce.</strong> \"Export to PDF\" rasterises the page, so the text is a picture — not selectable, not searchable, and several times larger. The export people actually wanted was sitting right below it under a name that gave no hint. They are now labelled — <em>PDF (text)</em>, real selectable text via the system print, listed first and recommended; <em>PDF (image)</em>, rasterised but saved without a dialog — in the toolbar and the command palette. (Gitee IK8QJQ)</li>\n          <li><strong>Word / EPUB / ODT / LaTeX exports match the preview again.</strong> Those formats go through Pandoc, which was being handed the raw file while the preview got a pass of leniency fixes first. A sublist indented two spaces therefore nested on screen and came out flat in a .docx. Pandoc now sees the same text you do. (Gitee IJXS8V)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.14</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.14 — the blank screen that swallowed your notes.</h2>\n        <ul>\n          <li><strong>A saved view that no longer existed could blank the whole editor, with no way back.</strong> Reported on Android as \"notes won't open\" — but the notes <em>were</em> opening: the toast fired, the status bar counted the lines, and then nothing appeared. The content area shows exactly one thing at a time and the editor is last in line, so a saved view marked open kept its place even after the view itself was gone. And because the pane's ‹ back button lived inside the same block that refused to render without a view, there was nothing left to click. Opening more files couldn't help — every one of them opened into a pane that couldn't draw. Android hit it most often, since a folder picked through the system file picker frequently can't read the views directory, but nothing about it was Android-only. The editor now takes over the moment a view stops resolving, and the back button always renders. (#245)</li>\n          <li><strong>The Aurora theme got a pass.</strong> Aurora-tinted hairline borders, translucent panel interiors that stay readable over the gradient, and no more full-screen strobe while dragging a panel edge. Thanks <a href=\"https://github.com/raopan2021\">@raopan2021</a>. (#244)</li>\n          <li><strong>The Arch package is current again.</strong> <code>solomd-bin</code> is live on the AUR and the in-repo packaging (stuck at 4.1.0) now tracks the real releases. Thanks <a href=\"https://github.com/gonwe\">@gonwe</a>. (#241)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.13</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.13 — a proper Gitea integration, 11 new themes, and two things that quietly did nothing.</h2>\n        <ul>\n          <li><strong>Gitea / Forgejo is a first-class sync target now.</strong> 4.11.12 made self-hosted sync <em>reachable</em>; this makes it real. Your Gitea token lives in its own keychain entry, so you can hold a GitHub and a Gitea token at the same time. Your server URL is remembered and checked before you commit to it. And SoloMD can now list your repositories and create the vault repo for you, instead of making you paste a clone URL. Contributed by <a href=\"https://github.com/JumpingY\">@JumpingY</a>, verified end-to-end against a real Gitea server. (#150)</li>\n          <li><strong>11 new community themes.</strong> Aurora, Deep Blue, Deep Green, Deep Purple, Frost Blue, Graphite Gray, Ink Blue, Rose Pink, Soft UI, VSCode Modern and Warm Sand — by <a href=\"https://github.com/raopan2021\">@raopan2021</a>, in Settings → Browse community themes. There is also a reload button next to your custom CSS file, so you can edit a theme in your editor and see it applied without restarting. (#239)</li>\n          <li><strong>Search in folder was dead if you had ever hidden the right sidebar.</strong> Ctrl/Cmd+Shift+F, the toolbar button and View → Search in Folder all did exactly nothing — and pressing again silently toggled it back off. The search panel lives in the right sidebar, and the sidebar's master hide switch outranked it, so the panel was being opened where nothing could draw it. All four entry points now un-hide the sidebar. (#209)</li>\n          <li><strong>Holding Cmd on a Mac no longer rescales the whole app by accident.</strong> Zoom-by-scroll stepped on any scroll event at all, so a trackpad under a resting finger — with Cmd held for ⌘S or ⌘Tab, as it usually is — would drift the entire UI down to minimum size. Incidental movement is now about five times less likely to zoom, while deliberate zooming is unchanged, and there is a switch in Settings → Basics to turn the gesture off completely. (#215)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.12</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.12 — sync works on your own server, and Android stops promising what it can't do.</h2>\n        <ul>\n          <li><strong>Self-hosted Gitea / Forgejo sync actually works now.</strong> The sync engine was never GitHub-specific — but the setup screen was. The provider picker only appeared <em>after</em> you saved a token, and saving validated every token against github.com and deleted it when that failed, so a self-hosted token could never survive. Pick your provider first, and we no longer ask github.com about tokens that aren't theirs. Verified end-to-end against a real Gitea server. (#229)</li>\n          <li><strong>Android no longer shows sync settings it can't run.</strong> The Android build has no Git engine inside it, but the app still drew the whole Sync panel and version-history UI — every button answered with a cryptic <code>Command not found</code>, and with auto-commit on you got an error on <em>every save</em>. Those controls are gone on Android now, replaced by a plain explanation. (#230)</li>\n          <li><strong>No more <code>.solomd</code> folder in every folder you open.</strong> Opening a folder just to read a note left a <code>.solomd</code> directory behind. That folder is for handing your open tabs between devices, so it's now only written inside genuinely cloud-synced folders — nothing is created in an ordinary local folder. (#236)</li>\n          <li><strong>OpenCode Go joins the AI provider list.</strong> 24 models behind one subscription, contributed by <a href=\"https://github.com/fengzhoujingshui\">@fengzhoujingshui</a>. (#232, #235)</li>\n          <li><strong>The Linux installer works on ARM.</strong> <code>install.sh</code> only ever fetched x86_64 packages, so the arm64 builds we already ship were unreachable on a Raspberry Pi or an ARM VM. Fixed by <a href=\"https://github.com/jysz\">@jysz</a>. (#220)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.11</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.11 — the Windows window controls work again, and Vim can save.</h2>\n        <ul>\n          <li><strong>Minimize and close work on Windows again.</strong> The unified title bar's window buttons were being blocked by a missing permission — clicks did nothing and you had to close from the taskbar. Fixed and verified on a real Windows build. The File menu got its <em>Exit</em> item back, dropdowns no longer close when you scroll under them, and reading mode now has its own minimize/close buttons. (#221, #223)</li>\n          <li><strong>Vim can save and quit.</strong> <code>:w</code>, <code>:wq</code>, <code>:x</code>, and <code>:q</code> now do what you'd expect — routed through SoloMD's real save and unsaved-changes flow. Along the way we closed a gap where a save fired right after typing could miss the last few keystrokes. (#222)</li>\n          <li><strong>No more phantom space after an apostrophe.</strong> The preview kept its typographic quotes on by default, and some fonts drew the curly apostrophe full-width — reading like an extra space. Quotes now render exactly as you type them; curly quotes are a new opt-in setting. (#216)</li>\n          <li><strong>Android: dictionary and translate apps show up again.</strong> Selecting text now offers your installed <code>PROCESS_TEXT</code> apps (offline dictionaries, translators). (#224)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.10</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.10 — one title bar on Windows, and three fixes you asked for.</h2>\n        <ul>\n          <li><strong>Windows gets a unified title bar.</strong> Three rows of chrome collapse into one — window controls, tabs, and toolbar share a single row, like the Mac app. Snap Layouts still work on the maximize button, and the MSI installer got proper branding. </li>\n          <li><strong>Select-all can't freeze the Windows editor anymore.</strong> Ctrl+A in the block editor is now handled by SoloMD itself instead of fighting the native textarea. (#189, #210)</li>\n          <li><strong>Code blocks wrap in Live Edit, and PDFs stop clipping them.</strong> The \"wrap long lines in code blocks\" setting now applies while editing, and PDF export no longer cuts off long code lines. (#211)</li>\n          <li><strong>Nested lists inside numbered lists keep their shape.</strong> A bulleted sub-list under an ordered list no longer flattens to one level. (#213)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.9</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.9 — zoom that keeps its aim, and four asked-for comforts.</h2>\n        <ul>\n          <li><strong>⌘+/⌘- zoom no longer breaks click targeting on macOS.</strong> Zoom now goes through the system webview (like Safari's), so the caret lands exactly under the pointer at any zoom level. (#192)</li>\n          <li><strong>The sidebar can't get stuck hidden anymore.</strong> Opening the outline — or any pane — from the shortcut, Settings, or the tab bar now also brings the auto-hidden sidebar back. (#207)</li>\n          <li><strong>Command palette speaks your language.</strong> All 85 commands follow Settings → Language across 14 locales; searching matches both the translated and the English name. (#177)</li>\n          <li><strong>New options:</strong> a solid (non-blinking) cursor toggle (#193) and a dedicated code font (#190). <strong>Copying tables from preview keeps their borders</strong> when pasted into mail clients. (#189)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.8</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.8 — split view lines up, positions stick.</h2>\n        <ul>\n          <li><strong>Split view stays level.</strong> The editor and preview now track each other pixel-accurately at any scroll position — soft-wrapped paragraphs, images, and raw HTML blocks no longer pull the two panes apart, and line numbers stay glued to their lines. (#203)</li>\n          <li><strong>Your scroll position survives tab switches.</strong> On Windows, switching away and back no longer resets the view to the top — in Edit, Split, and Live Edit modes alike. (#169)</li>\n          <li><strong><code>==Highlight==</code> renders in live edit.</strong> Same treatment as bold/italic: styled off the caret line, raw source when you edit it; code blocks stay verbatim. Typewriter mode now also centers the caret line in the Windows editor. (#199)</li>\n          <li><strong>Outline jump labels past <code>az</code> are fixed.</strong> Long documents no longer show <code>aundefined</code> markers. (#206)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.7</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.7 — one reliable Windows install path.</h2>\n        <ul>\n          <li><strong>MSI is now the only installed Windows channel.</strong> SoloMD installs to <code>C:\\Program Files\\SoloMD</code>; the portable ZIP remains available without installation.</li>\n          <li><strong>Old per-user installs migrate safely.</strong> On first launch from the MSI path, SoloMD verifies and removes the retired <code>%LOCALAPPDATA%\\SoloMD</code> NSIS installation, including its stale shortcuts and taskbar pin.</li>\n          <li><strong>Your work and settings stay untouched.</strong> The migration never removes <code>%APPDATA%\\app.solomd</code> or user documents.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.6</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.6 — Windows keeps the new icon after upgrading.</h2>\n        <ul>\n          <li><strong>Taskbar pins, shortcuts, and the running app now share one stable identity.</strong> Windows no longer falls back to an old or blank cached icon after an upgrade.</li>\n          <li><strong>This is a focused Windows hotfix.</strong> macOS and Android packages are refreshed for consistent downloads; their platform behavior is unchanged.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.5</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.5 — embedded HTML now works in live edit.</h2>\n        <ul>\n          <li><strong>Block HTML renders where you write.</strong> Containers such as <code>&lt;div&gt;</code>, <code>&lt;table&gt;</code>, and <code>&lt;details&gt;</code> now collapse into their rendered result when the caret leaves the block.</li>\n          <li><strong>Inline HTML behaves like Markdown formatting.</strong> Tags including <code>&lt;strong&gt;</code>, <code>&lt;sup&gt;</code>, <code>&lt;mark&gt;</code>, and <code>&lt;kbd&gt;</code> apply their visual meaning instead of remaining as noisy source.</li>\n          <li><strong>The source is always one click away.</strong> Moving the caret back into an HTML fragment reveals the exact markup for editing.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.4</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.4 — the new mark reaches the window chrome.</h2>\n        <ul>\n          <li><strong>The title bar now carries the new Portal mark.</strong> The legacy <code>#MD</code> text lockup is gone from the in-app toolbar.</li>\n          <li><strong>The About dialog matches.</strong> Both surfaces now render one shared brand component, so future identity updates cannot drift apart.</li>\n          <li><strong>macOS file icons are included and registered.</strong> The signed, notarized universal DMG maps Markdown files to the new warm-paper Portal document icon.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.3</span>\n          <time>Aug 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.3 — a new face, plus two fresh fixes.</h2>\n        <ul>\n          <li><strong>SoloMD has a new visual identity.</strong> The new orange <code>#</code> Portal app icon now ships consistently across macOS, Windows, Linux, iOS, Android, the App Store, and the website.</li>\n          <li><strong>Markdown files are recognizable at a glance.</strong> The default document icon is a warm paper sheet with an orange fold and the matching <code>#</code> Portal mark.</li>\n          <li><strong>Vim mode works on Windows again.</strong> Enabling Vim now switches the editor onto CodeMirror immediately, while the normal Windows editor keeps its IME-safe textarea path.</li>\n          <li><strong>Code blocks have a Copy button.</strong> Every rendered fenced block gets a pinned, accessible one-click copy action in its top-right corner.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.2</span>\n          <time>Jul 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.2 — four small fixes that were bugging you.</h2>\n        <ul>\n          <li><strong>Code blocks can wrap.</strong> New setting soft-wraps long code lines instead of a horizontal scrollbar — and PDF/print now always wraps, so wide code is never cut off on paper.</li>\n          <li><strong>Tabs remember where you were.</strong> Switching back to a tab no longer resets the view to the top when you had scrolled without clicking; line numbers stay put too.</li>\n          <li><strong>Vim <code>j</code>/<code>k</code> respect tables.</strong> Single-step motions land on a collapsed table/math/Mermaid block edge and expand it — same as the arrow keys — instead of hopping clear over.</li>\n          <li><strong>Full file names in the Explorer.</strong> New setting wraps long names instead of middle-ellipsis truncation.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.1</span>\n          <time>Jul 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.1 — the cursor stays where you put it.</h2>\n        <ul>\n          <li><strong>Chinese IME cursor jump fixed.</strong> Editing mid-paragraph and starting a pinyin composition right after could throw the caret to the top of the document and strand half-composed letters there — a debounced-sync race replacing the whole document mid-composition. Composition is never interrupted now, and external updates keep the caret in place.</li>\n          <li><strong>The update prompt stopped stealing your browser.</strong> Detecting a new version now shows a 12-second clickable toast; nothing opens unless you click it — and every update-related link (toast, settings check, About dialog) goes to solomd.app instead of GitHub.</li>\n          <li><strong>AI model catalog refreshed</strong> across all 14 providers (GPT-5.6 family, Grok 4.5, Claude Fable 5 / Opus 4.8, Gemini 3.6, GLM-5.2, Kimi K3 and more; retired DeepSeek v2 endpoints removed).</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11</span>\n          <time>July 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11 — broken tables fix themselves.</h2>\n        <ul>\n          <li><strong>Malformed tables render anyway.</strong> AI exports and PDF-to-Markdown tools often emit a delimiter row that doesn't match the header (an extra <code>|---|</code> cell, a missing one, an empty cell) — and the whole table silently collapsed into literal <code>| … |</code> text. SoloMD now repairs the delimiter row on the fly, like Typora and Obsidian, keeping each column's alignment. Code-block samples are left untouched.</li>\n          <li><strong>Numbered sections can become headings (opt-in).</strong> Reports often number sections as plain text — <code>6.2 Export licensing</code> — with no <code>#</code>. A new setting (off by default) promotes such lines to real headings by depth: <code>6.2</code> → h2, <code>6.2.1</code> → h3. Ordered lists, decimal sentences and single numbers are never touched.</li>\n          <li><strong>Headless export matches the app.</strong> The CLI (<code>solomd-export</code>, new <code>--number-headings</code> flag) and the MCP <code>export_note</code> tool (new <code>number_headings</code> arg) now run the exact same Markdown preprocessing as the in-app preview and DOCX export — one engine, identical output everywhere.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.10</span>\n          <time>July 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.10 — PlantUML + a preview width slider.</h2>\n        <ul>\n          <li><strong>PlantUML diagrams (opt-in).</strong> <code>```plantuml</code> fences render as diagrams in the preview and in live edit, through a configurable PlantUML server. Off by default — your notes never leave the machine unless you turn it on; point it at a self-hosted server to keep rendering on your own network.</li>\n          <li><strong>Preview width is yours.</strong> The preview / reading column width is now a slider (480–1600px, was a fixed 760px). \"Fit width\" still stretches to the window.</li>\n          <li><strong>Tables no longer trap the caret.</strong> In live edit, ↑/↓ used to teleport clear over rendered tables — and could skip whole paragraphs below them. The caret now walks every line, steps into a table (or math / Mermaid block) to edit its source, and the block re-renders when you leave.</li>\n          <li><strong>Code-block line numbers, fixed.</strong> Numbered code blocks no longer double their line spacing, C-style <code>/** */</code> comments no longer swallow the rest of the block into row 1, and the WYSIWYG editor now honors the same line-number setting as the preview.</li>\n          <li><strong>Clicks stay clicks (4.10.1).</strong> Clicking right after a tab switch — while diagrams/images were still rendering — could select multiple lines instead of placing the caret. The caret now stays where you pressed, even when the layout shifts mid-click.</li>\n          <li><strong>Open linked files with the default app (4.10.2).</strong> A Markdown link to a local PDF / Office file (<code>[report](./report.pdf)</code>) now opens in your system's default app instead of being converted to Markdown. New setting, on by default; links to <code>.md</code> / text / images still open inside SoloMD.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.9</span>\n          <time>July 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.9 — Android real folders + editor polish.</h2>\n        <p class=\"lead\">\n          The 4.9 line makes SoloMD open and edit your <strong>real folders on\n          Android</strong> — not a sandboxed copy. On Android 11+ (including\n          Honor / Huawei <strong>Magic OS</strong>, where the all-files\n          permission grants nothing) SoloMD now uses the <strong>Storage Access\n          Framework</strong>: pick a folder once, then read and write the actual\n          <code>.md</code> files in place, saved back through the system content\n          provider.\n        </p>\n        <ul>\n          <li><strong>Android folder vault (SAF).</strong> Open a real folder, edit files in place, full-width mobile layout.</li>\n          <li><strong>Save As fixed.</strong> It was writing empty files on Android — now the content lands in the file you choose.</li>\n          <li><strong>Find (Ctrl/⌘+F) scrolls as you type.</strong> The editor jumps to the first match while you type, like your browser — no more \"found nothing\" on long notes.</li>\n          <li><strong>Live-edit arrow keys cross blocks.</strong> ↑/↓/←/→ now move the caret between paragraphs in the Windows block editor — and as of 4.9.6 they respect soft-wrapped lines, so ↑ in a long paragraph no longer teleports over it.</li>\n          <li><strong>Line numbers on Windows (4.9.6).</strong> The \"show line numbers\" setting now works in the Windows editor, with a gutter that stays aligned under word wrap.</li>\n          <li><strong>Export Mermaid diagrams as PNG (4.9.6).</strong> Click a diagram → Export PNG or Copy image, at 2× resolution with a theme-matched background.</li>\n          <li><strong>Save dialog picks up your title (4.9.6).</strong> A never-saved note starting with <code># Heading</code> pre-fills \"Heading.md\" — stop retyping filenames.</li>\n          <li><strong>Linux launch fix.</strong> AppImage no longer aborts with <code>EGL_BAD_PARAMETER</code> on some Intel / Mesa setups.</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.7</span>\n          <time>June 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.7 — Windows gets a brand-new editor.</h2>\n        <p class=\"lead\">\n          <strong>Windows only.</strong> SoloMD on Windows now uses a completely\n          rebuilt <strong>block editor</strong> in place of CodeMirror.\n          WebView2's <code>contentEditable</code> dropped the\n          <strong>first character of CJK / IME input</strong> and\n          <strong>doubled punctuation</strong> (worst with Sogou) — a bug that\n          could not be fixed inside CodeMirror because it lives in WebView2\n          itself. The new editor types each block through a native\n          <code>&lt;textarea&gt;</code> on the OS-native IME path, so the\n          dropped-character and doubled-punctuation problems are gone.\n        </p>\n        <p>\n          The new Windows editor keeps <strong>full feature parity</strong>:\n          live Markdown preview, autocomplete &amp; slash commands\n          (<code>/</code>), focus &amp; typewriter mode, smart list continuation,\n          AI rewrite (<code>Ctrl+J</code>), in-document find &amp; replace\n          (<code>Ctrl+F</code>), clipboard image paste, task-checkbox toggle,\n          undo / redo, Tab indent, spellcheck and word-wrap.\n        </p>\n        <p style=\"opacity:.8;\">\n          <strong>macOS, Linux, iOS and Android are unaffected</strong> — they\n          keep the existing CodeMirror editor. Also in 4.7: the command palette\n          no longer jumps when you hover or wheel-scroll the list (#93).\n        </p>\n        <p class=\"version-row\" style=\"margin-top:24px;\">\n          <span class=\"version-tag\">v4.9</span>\n          <time>July 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.9 — Android opens your real vault.</h2>\n        <p class=\"lead\">\n          On Android, SoloMD's only freely-readable folder used to be a\n          sandbox under <code>/Android/data</code> that no file manager can\n          reach on an unrooted phone — so you could never point the app at\n          your actual notes folder. 4.9 adds <strong>All-files access</strong>:\n          grant it once and <strong>Open Folder</strong> lets you browse to a\n          real vault anywhere on the device (<code>Documents</code>, a\n          Syncthing / Dropbox folder, an SD card) and <strong>edit files in\n          place</strong> — no copying into the sandbox. The file tree, search,\n          version history and save all work against your real paths (#148,\n          #151).\n        </p>\n        <p style=\"margin-top:14px;\">\n          Also in 4.9, a sweep of reported bugs.\n          <strong>The macOS window can be dragged by its title bar again</strong>\n          (#153) — the drag call had been silently rejected by a missing\n          permission ever since the unified title bar shipped; double-click\n          to zoom is back too. <strong>The \"File Changed on Disk\" dialog no\n          longer interrupts typing on Android</strong> (#148) — the app's own\n          saves were mistaken for external edits because Android delivers\n          file events seconds late; changes are now judged by the file's\n          modification time instead. The update-available notice now opens\n          the solomd.app download page (reachable in mainland China, with the\n          Gitee mirror) instead of GitHub (#154), and the no-op\n          \"Reveal in Finder\" menu item is hidden on phones.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.11</strong> — three reported bugs, fixed.\n          <strong>Android can open files again</strong> (#148): files handed\n          over by a file manager, \"Open with\", or the in-app picker arrive as\n          <code>content://</code> URIs that no filesystem call can read — they\n          now import into the SoloMD folder (keeping the original filename, or\n          naming from the doc's first heading) and open normally, mirroring the\n          iOS Files-app flow. <strong>GitHub sync no longer pushes to\n          <code>main</code> while pulling from <code>master</code></strong>\n          (#147) — a second device could get permanently stuck never seeing the\n          first device's pushes; pull now normalizes the branch the same way\n          push does, with a fallback for legacy master-only remotes.\n          And <strong>closing a tab returns to the adjacent tab</strong>\n          instead of jumping to the first one in the list (#149 — root cause\n          contributed by the reporter, thanks!).\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.10</strong> — quality-of-life sweep.\n          <strong>Ctrl+A finally selects the whole document</strong> in the\n          Windows live editor (it used to stop at the current paragraph), so\n          select-all → copy / delete / type-over behaves like any other editor.\n          <strong>Deleting a file or folder now moves it to the system\n          Trash / Recycle Bin</strong> instead of erasing it permanently (#112),\n          and single entries can be removed from the Recent-files list. A new\n          <strong>“single newline = line break”</strong> setting keeps the\n          preview, the Windows live editor and every export (PDF, DOCX, Pandoc)\n          agreeing on what Enter means (#141). <strong>Font size &amp; family\n          now apply everywhere</strong> — live-edit blocks, the preview pane and\n          reading mode (#143). Switching tabs <strong>keeps your cursor and\n          scroll position</strong> (#144), “open at startup in reading mode”\n          works again with restore-tabs off, the settings pages no longer share\n          one scroll position, and the toolbar <strong>AI-rewrite button</strong>\n          works on Windows (#126).\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.9</strong> — iOS file opening, fixed for real. Opening a\n          Markdown file from the <strong>Files app</strong>, AirDrop or another\n          app no longer fails with \"No such file or directory\" (#139) — the\n          share sheet handed over a percent-encoded <code>file://</code> URL\n          that was never decoded. <strong>Recent files survive app\n          updates</strong> (iOS moves the app container on every update; stored\n          paths are re-anchored automatically), <strong>Open Folder</strong> now\n          pins the workspace to SoloMD's Documents folder, and the <strong>tab\n          bar scrolls with a swipe</strong>. Also on desktop: local\n          <strong>SVG previews</strong> stay visible across windows (#142,\n          thanks @beihai23).\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.1</strong> — fixes. <strong>Find &amp; Replace</strong> is\n          discoverable again (a command-palette entry; it always lived behind\n          Ctrl+F, #137). Clicking a relative <code>.md</code> link inside a\n          <strong>WSL</strong> vault no longer fails with “os error 3” (#138).\n          A pinned <strong>reading-mode</strong> startup with restore-tabs off no\n          longer opens a blank window (#128). The <strong>macOS app icon</strong>\n          is now a proper rounded squircle with margin (#111). And an\n          expired/revoked <strong>GitHub sync</strong> token now prompts you to\n          reconnect instead of throwing a raw 401.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.0</strong> — <strong>image hosting (图床)</strong>. Paste,\n          drop or pick an image and SoloMD can now upload it to an external\n          image host and insert the returned URL — instead of only copying it\n          into a local folder, like Typora / MarkText. Five backends:\n          <strong>PicGo</strong> (local server), a <strong>custom command</strong>\n          (PicGo-Core / uPic / any script), <strong>SM.MS</strong>,\n          <strong>S3-compatible</strong> (Aliyun OSS / Tencent COS / Cloudflare\n          R2 / MinIO), and a <strong>GitHub repo + CDN</strong>. Plus\n          “insert image from URL” and a “upload all local images in this note”\n          command. Auto-upload on paste falls back to a local copy if the host\n          is unreachable. Configure in Settings → Writing.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.7.4</strong> — <strong>Backspace / Delete</strong> are\n          reliable again in the Windows editor. Each paragraph there is its own\n          text box, so pressing Backspace at the very start of a block (or\n          Delete at its very end) used to hit the box edge and do nothing —\n          delete felt hit-or-miss. Those boundary presses now act on the whole\n          document, joining paragraphs or removing the blank line just like a\n          normal editor, with the caret and focus following along.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.7.3</strong> — <strong>PDF export</strong> no longer\n          crashes on themes or content using modern CSS color functions\n          (<code>color()</code>, <code>oklch()</code>, <code>color-mix()</code>),\n          and a failed export no longer leaves the window frozen or zoomable\n          (#115). Plus: <strong>split-view scroll sync</strong> works again on\n          Windows — the editor and preview had stopped following each other\n          after the 4.7 Windows editor rebuild.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.7.2</strong> — the file tree gets a <strong>resizable\n          sidebar</strong> (drag the edge, 180–600&nbsp;px), <strong>per-filetype\n          icons</strong>, and middle-ellipsis truncation for long filenames; the\n          macOS title bar no longer overlaps the in-app toolbar (#121). Plus a\n          <strong>PDF export fix</strong>: body paragraphs and list items are no\n          longer sliced in half across page breaks.\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.7.1</strong> — live preview now renders bullet lists, task\n          checkboxes and horizontal rules (not just headings) across macOS /\n          Linux / iOS / Android; source mode is genuinely plain again\n          (headings no longer enlarged when live-preview is off). Plus:\n          file-tree <strong>copy path / relative path</strong> (#120) and a\n          <strong>close-folder</strong> button (#118), a\n          <strong>limit-editor-width</strong> readable column (#109), and the\n          fit-width toggle now works in reading mode (#117).\n        </p>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.6</span>\n          <time>June 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.6 — the knowledge-graph half, built.</h2>\n        <p class=\"lead\">\n          A full <strong>design-system + Vue component-library rebuild</strong>\n          (warm-neutral surfaces, orange <code>#ff9f40</code> accent) and a\n          <strong>unified macOS title bar</strong> (traffic lights inlined into\n          the toolbar) — plus the seven structural features that used to be the\n          one thing a knowledge-graph editor like Tolaria did and SoloMD didn't.\n          All on disk as plain <code>.md</code> / YAML. No new file format.\n        </p>\n        <div class=\"pillars\">\n          <div class=\"pillar\">\n            <h3>Properties inspector (<code>⌘⇧I</code>)</h3>\n            <p>\n              A dedicated frontmatter editor — date, relation, status and tag\n              pickers — instead of hand-editing YAML. Writes straight back to\n              the note's front-matter.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Type-driven sidebar</h3>\n            <p>\n              <code>type:&lt;Name&gt;</code> notes become first-class\n              collapsible sidebar sections (types-as-lenses), each with a custom\n              icon, color, order, and pinned properties.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Typed relationships</h3>\n            <p>\n              <code>belongs_to</code> / <code>related_to</code> /\n              <code>has</code> frontmatter fields with <strong>automatic\n              inverses</strong> — declare one side, the other resolves itself.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Relationship graph (\"Neighborhood\")</h3>\n            <p>\n              A per-note explorer of outgoing <em>and</em> inverse\n              relationships — walk the graph one hop at a time from whatever\n              note you're in.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Saved filtered views</h3>\n            <p>\n              Persistent sidebar views stored as\n              <code>.solomd/views/*.yml</code> — filter by type, status, date,\n              or regex, and they stay put across launches.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Inbox workflow</h3>\n            <p>\n              <code>⌘E</code> marks the current note organized and\n              auto-advances to the next — a real inbox-zero loop for triaging\n              captured notes.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>tldraw whiteboards</h3>\n            <p>\n              Markdown-backed boards via a <code>```tldraw</code> fence —\n              durable in the note's <code>.md</code>, and cross-compatible with\n              Tolaria's on-disk board format.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Design-system UI + unified title bar</h3>\n            <p>\n              A warm-neutral surface palette with an orange\n              <code>#ff9f40</code> accent, rebuilt on a proper Vue component\n              library, and a unified macOS title bar that inlines the traffic\n              lights into the toolbar.\n            </p>\n          </div>\n        </div>",
    "<h2>The five pillars (v4.0)</h2>\n        <p>\n          Each is in core. Toggleable via a setting. Built to play\n          nicely with your existing notes — no schema migration, no\n          new file format, no required cloud account.\n        </p>\n        <div class=\"pillars\">\n          <div class=\"pillar\">\n            <h3>1 · Inline Agent Panel</h3>\n            <p>\n              Right-side first-class panel (peer to Outline / Backlinks /\n              Tags / History). Streamed chat-with-vault routed through\n              the in-process MCP surface and your existing 14-provider\n              AI stack. <code>[[wikilink]]</code> citations resolve to\n              real notes; tool-call cards expand inline showing every\n              read/write the agent makes. Reply too long? <strong>Insert</strong>\n              and <strong>Copy</strong> buttons drop it into the active\n              editor — replaces selection if any, else inserts at the\n              cursor. Run history persists as plain markdown under\n              <code>.solomd/agent-runs/</code> — grep-able,\n              git-trackable.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>2 · Agent Recipes / Scheduled Runs</h3>\n            <p>\n              Declarative agent jobs as YAML in your vault:\n              <code>&lt;workspace&gt;/.solomd/agents/*.yml</code>.\n              Triggers: <code>schedule</code> (cron), <code>on-save</code>,\n              <code>on-commit</code>, <code>on-tag-add</code>, manual.\n              <strong>Safety rails are non-negotiable</strong>: every\n              run gets its own AutoGit branch <code>agent/&lt;recipe&gt;/&lt;run-id&gt;</code>,\n              writes are reviewable via accept / reject UI before\n              merging, and a per-run <code>write-cap</code> (default 5,\n              hard ceiling 50) prevents runaway loops. Rejected runs\n              have the branch hard-deleted — zero residue. Ships with\n              an <strong>11-recipe cookbook</strong> (weekly review,\n              daily summary, TODO extraction, translation, citation\n              cleanup, CJK proofread agent, …) — install one, edit it,\n              run it.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>3 · Agent Trace View</h3>\n            <p>\n              Every run (Panel chat OR Recipe) emits a\n              <code>trace.jsonl</code> per step:\n              <code>prompt</code> / <code>model_call</code> /\n              <code>tool_call</code> / <code>tool_result</code> /\n              <code>git_commit</code> / <code>done</code>. Step cards\n              expand to show args, results, token counts, cost\n              estimate, AutoGit branch refs.\n              <strong>Replay-from-step</strong> button rewinds the run\n              to step N and re-executes from there with edited inputs —\n              the path to self-correcting recipes. New MCP tool\n              <code>read_agent_trace(run_id)</code> exposes traces to\n              other agents.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>4 · Workspace Federation</h3>\n            <p>\n              <code>solomd-mcp --workspace path1 --workspace path2 --workspace path3</code>\n              — one MCP session, many vaults. Tool signatures gain an\n              optional <code>workspace</code> parameter; default = first\n              passed (fully back-compat with single-workspace clients).\n              AutoGit branches stay isolated per workspace. <strong>Settings\n              → Integrations</strong> adds an MCP profiles UI: name a\n              bundle of vaults, copy the Claude Desktop config snippet\n              with one click.\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>5 · Ollama first-class</h3>\n            <p>\n              We do <strong>NOT</strong> bundle a local LLM runtime —\n              Ollama already does that well. v4.0 polishes the\n              integration: auto-detect at <code>localhost:11434</code>\n              (green status indicator in Settings → AI), one-click\n              install hint when not found, three model presets\n              (<code>rewrite</code> → qwen2.5:7b · <code>quick</code> →\n              qwen2.5:1.5b · <code>cjk</code> → qwen2.5:14b),\n              recommended pull from inline UI when no models installed.\n              Recipes can specify <code>provider: local</code> (alias\n              of ollama) for cheap autonomous loops with zero cloud\n              cost. <em>Your notes never leave the machine</em> — true\n              today via BYOK Ollama; v4.0 makes it discoverable.\n            </p>\n          </div>\n        </div>",
    "<h2>🛡️ Safety rails (the bit nobody else does)</h2>\n        <ul>\n          <li>\n            <strong>AutoGit branch sandbox.</strong> Every recipe run\n            starts on its own branch. Your <code>main</code> stays\n            untouched until you click Accept. A rejected run leaves\n            <em>nothing</em> in your history — branch deleted, file\n            tree reverted.\n          </li>\n          <li>\n            <strong>Per-run write cap.</strong> A model that asks to\n            write 50 files when the cap is 5 gets refusals at the 6th\n            tool call. No half-applied state, no surprise mass-edits.\n          </li>\n          <li>\n            <strong>Refuses to start on a dirty workspace.</strong> If\n            you have uncommitted edits when a recipe fires, it errors\n            out cleanly instead of sweeping your work-in-progress into\n            an agent commit.\n          </li>\n          <li>\n            <strong>Path-traversal hardening.</strong> Both the\n            in-process tool surface and every Tauri command that joins\n            user-supplied <code>run_id</code> / <code>path</code>\n            arguments now reject <code>..</code> segments and absolute\n            paths upfront. The agent literally can't write outside its\n            workspace.\n          </li>\n          <li>\n            <strong>Replayable trace.</strong> Every step on disk in\n            line-delimited JSON. Suspicious behavior in the panel? Walk\n            the trace, find the bad step, replay from N–1 with edited\n            inputs.\n          </li>\n        </ul>",
    "<h2>Quality bar</h2>\n        <ul>\n          <li>\n            <strong>First-run wizard.</strong> New install meets the\n            Agent Panel within 60 seconds — guides you through BYOK key\n            entry OR Ollama setup. Re-launchable from Help.\n          </li>\n          <li>\n            <strong>Recipe cookbook (11 starters).</strong> Settings →\n            Recipes → Browse cookbook. Weekly review, daily summary,\n            TODO extraction, translation pass, citation cleanup, CJK\n            proofread agent, link-rot detector, frontmatter normalizer,\n            outline-to-blog, refactor pass, weekly tag triage. Install\n            one, edit the prompt, run it.\n          </li>\n          <li>\n            <strong>Public REST API</strong> (localhost only, token\n            auth). Same surface as MCP for clients that don't speak MCP\n            yet — Alfred / Raycast / n8n / your own scripts.\n          </li>\n          <li>\n            <strong>BYOK cost meter.</strong> Per-provider running\n            tokens-spent counter, opt-in. Settings → Integrations.\n          </li>\n          <li>\n            <strong>Localization.</strong> ja / ko translations\n            scaffolded for README + iPad metadata. en/zh remain the\n            full-coverage UI languages.\n          </li>\n        </ul>",
    "<h2>UX polish you'll notice on day one</h2>\n        <ul>\n          <li>\n            <strong>IME composition guard everywhere.</strong> Pinyin\n            users typing Chinese, Japanese kana mode, Korean Hangul —\n            pressing Enter to commit a candidate no longer fires \"send\"\n            in chat / \"rename\" in file tree / \"open\" in command palette\n            and search. Fixed across <strong>7 input surfaces</strong>.\n          </li>\n          <li>\n            <strong>Insert / Copy on assistant replies.</strong> Two\n            buttons under each completed reply. Insert respects the\n            current editor selection (replaces it) or falls back to\n            cursor insertion. Copy is plain clipboard.\n          </li>\n          <li>\n            <strong>Window UX on macOS.</strong> Launch activation\n            timing is right — SoloMD becomes frontmost on cold start\n            instead of opening behind Finder. Restored window position\n            stays inside the current monitor work area; bad saved\n            state from a now-disconnected secondary monitor recenters\n            cleanly instead of opening off-screen.\n          </li>\n          <li>\n            <strong>Stuck \"streaming…\" with no error.</strong> Fixed.\n            A misconfigured provider (e.g. Ollama with a model that\n            isn't pulled) used to hang the panel forever. Now you see\n            a red error banner with the actual response from the\n            backend, and the Send button comes back.\n          </li>\n        </ul>",
    "<h2>What v4.0 explicitly skips (and why)</h2>\n        <p>\n          Saying \"no\" is part of the product. These were considered\n          and consciously not shipped:\n        </p>\n        <ul>\n          <li>\n            <strong>Bundled local LLM runtime.</strong> Ollama already\n            covers this; re-implementing violates \"write less code we\n            maintain forever.\" BYOK provider stays the path.\n          </li>\n          <li>\n            <strong>Online recipe marketplace.</strong> Server ops +\n            moderation = off-mission. Cookbook ships in-tree.\n          </li>\n          <li>\n            <strong>Multi-user / team agents.</strong> Violates \"one\n            window, one writer.\" This product is for the single\n            author; collaboration belongs to a different product.\n          </li>\n          <li>\n            <strong>Copilot-style ghost-text autocomplete.</strong>\n            Different brand. Ghost-text dilutes the writer's voice;\n            our agents work at vault granularity instead, with batched\n            reviewable writes.\n          </li>\n        </ul>",
    "<h2>Upgrade notes</h2>\n        <ul>\n          <li>\n            <strong>No file-format changes.</strong> Your existing\n            <code>.md</code> files, AutoGit history, sync setup, BYOK\n            keys all carry over untouched.\n          </li>\n          <li>\n            <strong>Agent Panel auto-enables on first launch.</strong>\n            v3.6.x users had a hidden <code>showAgentPanel: false</code>\n            from the v4-beta scaffolding period; a one-time migration\n            flips it on so you actually see the marquee feature.\n            Toggle off via <code>⌘⇧P → View: Toggle Agent Panel</code>\n            if you don't want it.\n          </li>\n          <li>\n            <strong>Settings layout adds <em>Recipes</em> and\n            <em>Cost meter</em> tabs</strong> under\n            <em>Integrations</em>. Existing settings keep their\n            previous tabs.\n          </li>\n          <li>\n            <strong>The MCP server (<code>solomd-mcp</code>) gained a\n            <code>--workspace</code> flag</strong> (repeatable). Older\n            MCP clients with a single workspace argument keep working\n            unchanged; the federation behavior is opt-in.\n          </li>\n        </ul>",
    "<h2>🔮 What's next</h2>\n        <p>\n          The 5 pillars + quality bar are the headline drop. The\n          <em>v4.x and beyond</em> open directions on the\n          <a href=\"https://github.com/zhitongblog/solomd/blob/main/docs/roadmap.md\">roadmap</a>:\n          a sandboxed scripting API, a CLI v2 (rewrite / commit /\n          semantic search / recipe-trigger from terminal), and the\n          long-deferred <em>\"should SoloMD become a business?\"</em>\n          question (paid sync — original v3.0 question, still\n          unanswered, no engineering until decided).\n        </p>",
  ],
  thanks: "Thanks to everyone who filed issues, opened PRs, and ran the\n        v4-beta builds through real vaults during the quiet phase.\n        v4.0 shipped because dogfooding caught the bugs that\n        integration tests didn't.\n        Earlier: <a href=\"/blog/\">browse the blog →</a>",
};

export default data;
